const EXCLUDE_NAME_PATTERNS = ['wapp', 'personality', 'love language', 'lovelanguage', 'love_language', 'mindspree', 'html', 'legal', 'shared', 'monorepo', 'chat ai', 'chatbot'];
const out = [];
const seen = {};
const excluded = [];
for (const item of $input.all()) {
  const b = item.json || {};
  for (const p of (b.projects || [])) {
    const pid = p.project_id ? String(p.project_id) : '';
    if (!pid || seen[pid]) continue;
    seen[pid] = true;
    const name = String(p.name || '');
    const lower = name.toLowerCase();
    let blocked = false;
    for (const pat of EXCLUDE_NAME_PATTERNS) {
      if (lower.indexOf(pat) !== -1) blocked = true;
    }
    if (blocked) {
      excluded.push(name);
      continue;
    }
    out.push({ json: { projectId: pid, projectName: name, excludedProjects: excluded } });
  }
}
return out;

const TAG = 'to_review';
const UNASSIGNED_TAG = 'review_unassigned';
const SOURCE_PREFIX = 'en';
const MAX_KEYS_PER_TASK = 500;
const LINGUIST_ROLE_ID = 4;
const BLOCKED_EMAILS = ['support@lokalise.com'];
const NON_TRANSLATABLE_LOCALES = ['pst', 'cus', 'pt_old'];

const PROJECT_LABELS = {
  'ResumeWise': { label: 'ResumeWise', side: 'FE' },
  'ResumeWise - backend/emails': { label: 'ResumeWise', side: 'BE' },
  'QRcreate': { label: 'QRcreate', side: 'FE' },
