  'myevisa.com - DEV': { label: 'myevisa.com', side: 'DEV' }
};

const deriveLabel = (rawName) => {
  const mapped = PROJECT_LABELS[rawName];
  if (mapped) return mapped;
  const clean = String(rawName || '').split('"').join('').trim();
  const lower = clean.toLowerCase();
  let side = 'FE';
  if (lower.indexOf('backend') !== -1 || lower.indexOf('email') !== -1 || lower.indexOf('(be') !== -1 || lower.indexOf(' be)') !== -1 || lower.indexOf('- be') !== -1) side = 'BE';
  let label = clean;
  const cutMarkers = [' (fe)', ' (be)', ' (backend)', ' - backend/emails', ' - backend', ' (be- emails)', ' (emails)', ' - emails', ' - lokalise keys'];
  for (const m of cutMarkers) {
    const at = label.toLowerCase().indexOf(m);
    if (at !== -1) label = label.slice(0, at);
  }
  return { label: label.trim(), side: side };
};

const DESCRIPTION = [
  'CONTEXT AND QUESTIONS',
  'Wherever possible, we have provided relevant screenshots, string descriptions and or relevant product links: please make sure you check any added info.',
  'If you have any questions please use the Comment feature at key level (not in your translation). [https://docs.lokalise.com/en/articles/1400643-comments]',
  'STYLE GUIDES (check folder per Product): https://drive.google.com/drive/folders/1O_6nqK3rUSmJWbYfkiZmrnB3HF3YVvix',
  'TO KEEP ALWAYS IN MIND:',
  '*Run all basic QA checks (no mismatched placeholder etc)',
  '*Check carefully strings marked with z_admin_tagged (if any)',
  '*Follow the style guide for your language',
  '*Use glossary terms consistently (you can add and edit terms directly in the [Multiproject/shared - USE ALSO TO UPDATE GLOSSARY FOR ALL PROJECTS](https://app.lokalise.com/project/46552447679363c70f7ef8.58193285/) glossary, which is shared across products)',
  '---------------------------------------------------------------------------------------------------------------------',
  'Lokalise Help Center: https://docs.lokalise.com/en/articles/6854191-translation-editor'
].join('\n');

const meta = {};
for (const p of $('Flatten Projects').all()) {
  const j = p.json || {};
  meta[String(j.projectId)] = j.projectName || '';
}

const byProject = {};
const fetchProblems = [];
for (const item of $input.all()) {
  const b = item.json || {};
  if (b.error) {
    fetchProblems.push(typeof b.error === 'string' ? b.error : JSON.stringify(b.error).slice(0, 300));
    continue;
  }
  const pid = b.project_id ? String(b.project_id) : '';
  if (!pid) continue;
  if (!byProject[pid]) byProject[pid] = { keys: [], contributors: [] };
  if (Array.isArray(b.keys)) byProject[pid].keys = byProject[pid].keys.concat(b.keys);
  if (Array.isArray(b.contributors)) byProject[pid].contributors = byProject[pid].contributors.concat(b.contributors);
}

const isSource = (iso) => String(iso || '').toLowerCase().indexOf(SOURCE_PREFIX) === 0;
const isTranslatable = (iso) => NON_TRANSLATABLE_LOCALES.indexOf(String(iso).toLowerCase()) === -1;
const isEmpty = (v) => {
  if (v === null || v === undefined || v === '') return true;
  if (typeof v === 'object') return Object.keys(v).every((k) => !v[k]);
  return false;
};
const canReview = (c) => {
  if (c.is_admin === true) return false;
  if (c.is_pending === true) return false;
  if (BLOCKED_EMAILS.indexOf(String(c.email)) !== -1) return false;
  for (const p of (c.permissions || [])) {
    if (String(p) === 'review') return true;
  }
  return false;
};

const daysToWednesday = ((3 - $now.weekday) + 7) % 7 === 0 ? 7 : ((3 - $now.weekday) + 7) % 7;
const dueDate = $now.plus({ days: daysToWednesday }).set({ hour: 17, minute: 0, second: 0, millisecond: 0 }).toFormat('yyyy-MM-dd HH:mm:ss');
const stamp = $now.toFormat('ddMMyy');
const out = [];

for (const pid of Object.keys(byProject)) {
  const projectName = meta[pid] || '';
  const data = byProject[pid];
  if (!data.keys.length) continue;

  const primary = {};
  const fallback = {};
  const emailById = {};
  for (const c of data.contributors) {
    if (!canReview(c)) continue;
    emailById[String(c.user_id)] = String(c.email || '');
    for (const l of (c.languages || [])) {
      if (l.is_writable !== true) continue;
      const iso = String(l.lang_iso || '');
      if (!iso || isSource(iso) || !isTranslatable(iso)) continue;
      const bucket = Number(c.role_id) === LINGUIST_ROLE_ID ? primary : fallback;
      if (!bucket[iso]) bucket[iso] = [];
      if (bucket[iso].indexOf(c.user_id) === -1) bucket[iso].push(c.user_id);
    }
  }

  const langNeed = {};
  const keyEntries = [];
  let skippedUntranslated = 0;
  let skippedArchivedOrHidden = 0;
  for (const k of data.keys) {
    if (k.is_archived === true || k.is_hidden === true) {
      skippedArchivedOrHidden = skippedArchivedOrHidden + 1;
      continue;
    }
    let qualifies = false;
    for (const t of (k.translations || [])) {
      const iso = String(t.language_iso || '');
      if (!iso || isSource(iso) || !isTranslatable(iso)) continue;
      if (isEmpty(t.translation)) continue;
      if (t.is_reviewed === true && t.is_unverified !== true) continue;
      qualifies = true;
      langNeed[iso] = (langNeed[iso] || 0) + 1;
    }
    if (qualifies) {
      keyEntries.push({ key_id: k.key_id, tags: Array.isArray(k.tags) ? k.tags : [], base_words: Number(k.base_words) || 0 });
    } else {
      skippedUntranslated = skippedUntranslated + 1;
    }
  }
  if (!keyEntries.length) continue;

  const languages = [];
  const gaps = [];
  const gapLanguages = [];
  const assignees = {};
  for (const iso of Object.keys(langNeed)) {
    const users = (primary[iso] && primary[iso].length) ? primary[iso] : (fallback[iso] || []);
    if (users.length) {
      languages.push({ language_iso: iso, users: users });
      const emails = [];
      for (const u of users) emails.push(emailById[String(u)] || String(u));
      assignees[iso] = emails;
    } else {
      gaps.push({ language_iso: iso, strings_needing_review: langNeed[iso] });
      gapLanguages.push(iso);
    }
  }
  if (!languages.length) continue;

  const naming = deriveLabel(projectName);
  const chunkCount = Math.ceil(keyEntries.length / MAX_KEYS_PER_TASK);
  for (let c = 0; c < chunkCount; c++) {
    const slice = keyEntries.slice(c * MAX_KEYS_PER_TASK, (c + 1) * MAX_KEYS_PER_TASK);
    const keyIds = [];
    let sourceWords = 0;
    for (const e of slice) {
      keyIds.push(Number(e.key_id));
      sourceWords = sourceWords + (e.base_words || 0);
    }
    const suffix = chunkCount > 1 ? ' (part ' + (c + 1) + ' of ' + chunkCount + ')' : '';
    out.push({ json: {
      projectId: pid,
      projectName: projectName,
      projectLabel: naming.label,
      projectSide: naming.side,
      taskTitle: naming.label + '_' + stamp + ' ' + naming.side + suffix,
      taskDescription: DESCRIPTION,
      dueDate: dueDate,
      keyIds: keyIds,
      keyTags: slice,
      sourceWords: sourceWords,
      totalWords: sourceWords * languages.length,
      languages: languages,
      languageCount: languages.length,
      assigneesByLanguage: assignees,
      gaps: gaps,
      gapLanguages: gapLanguages,
      skippedUntranslatedKeys: skippedUntranslated,
      skippedArchivedOrHiddenKeys: skippedArchivedOrHidden,
      chunk: c + 1,
      chunkCount: chunkCount,
      fetchProblems: fetchProblems
    } });
  }
}
return out;

const r = $json || {};
const plan = $('Build Review Task Plans').item.json || {};
const task = r.task || {};
const ok = !!task.task_id;
let errText = null;
if (!ok) {
  if (r.error) errText = typeof r.error === 'string' ? r.error : JSON.stringify(r.error).slice(0, 400);
  else errText = JSON.stringify(r).slice(0, 400);
}
return { json: {
