for (const item of $input.all()) {
  const b = item.json || {};
  if (b.error) continue;
  const t = b.task || {};
  if (!t.task_id) continue;
  const title = String(t.title || ('Task ' + t.task_id));
  const srcIso = String(t.source_language_iso || 'en');
  const srcName = SOURCE_NAMES[srcIso] || srcIso;
  const langs = t.languages || [];
  let perLangWords = 0;
  if (langs.length) perLangWords = langs[0].words_count || 0;
  const grid = [];
  grid.push(['Task name', title]);
  grid.push(['Task description', String(t.description || '')]);
  grid.push(['Type', String(t.task_type || '')]);
  grid.push(['Created at', fmtDate(t.created_at)]);
  grid.push(['Created by', person(t.created_by_fullname, t.created_by_email)]);
  grid.push(['Due date', fmtDate(t.due_date)]);
  grid.push(['Source words', perLangWords]);
  grid.push(['Words total', t.words_count || 0]);
  grid.push(['Keys total', t.keys_count || 0]);
  grid.push(['Segments total', '']);
  grid.push(['Repetitions', '']);
  grid.push(['']);
  grid.push(['', 'TM 100%', 'TM 95-99%', 'TM 85-94%', 'TM 75-84%', 'TM 50-74%', 'TM 0-49%', 'Assignees']);
  let pending = 0;
  for (const l of langs) {
    const tm = (l.tm_leverage && l.tm_leverage.value) ? l.tm_leverage.value : {};
    if (l.tm_leverage && l.tm_leverage.status !== 'completed') pending = pending + 1;
    const who = [];
    for (const u of (l.users || [])) {
      const label = person(u.fullname, u.email);
      if (label) who.push(label);
    }
    grid.push([
      srcName + ' (' + srcIso + ') → ' + clean(l.language_name) + ' (' + String(l.language_iso) + ')',
      tm['100%'] || 0,
      tm['95%+'] || 0,
      tm['85%+'] || 0,
      tm['75%+'] || 0,
      tm['50%+'] || 0,
      tm['0%+'] || 0,
      who.join(', ')
    ]);
  }
  out.push({ json: {
    taskId: t.task_id,
    taskTitle: title,
    tabName: sanitiseTab(title),
    projectName: b.project_name || '',
    languageCount: langs.length,
    analysisPending: pending,
    rowCount: grid.length,
    grid: grid
  } });
}
return out;

const b = $input.first().json || {};
if (b.error) return [];
const keep = {};
for (const it of $('Build Tab Grid').all()) {
  const j = it.json || {};
  if (j.tabName) keep[String(j.tabName)] = true;
}
const requests = [];
const hiding = [];
const staying = [];
for (const s of (b.sheets || [])) {
  const p = s.properties || {};
