].join('\n');

const meta = {};
for (const p of $('Flatten Projects').all()) {
  const j = p.json || {};
  meta[String(j.projectId)] = j.projectName || '';
}

const byProject = {};
const fetchProblems = [];
for (const item of $input.all()) {
  const b = item.json || {};
  if (b.error) {
    fetchProblems.push(typeof b.error === 'string' ? b.error : JSON.stringify(b.error).slice(0, 300));
    continue;
  }
  const pid = b.project_id ? String(b.project_id) : '';
  if (!pid) continue;
  if (!byProject[pid]) byProject[pid] = { keys: [], contributors: [] };
  if (Array.isArray(b.keys)) byProject[pid].keys = byProject[pid].keys.concat(b.keys);
  if (Array.isArray(b.contributors)) byProject[pid].contributors = byProject[pid].contributors.concat(b.contributors);
}

const isSource = (iso) => String(iso || '').toLowerCase().indexOf(SOURCE_PREFIX) === 0;
const isTranslatable = (iso) => NON_TRANSLATABLE_LOCALES.indexOf(String(iso).toLowerCase()) === -1;
const isEmpty = (v) => {
  if (v === null || v === undefined || v === '') return true;
  if (typeof v === 'object') return Object.keys(v).every((k) => !v[k]);
  return false;
};
const canReview = (c) => {
  if (c.is_admin === true) return false;
  if (c.is_pending === true) return false;
  if (BLOCKED_EMAILS.indexOf(String(c.email)) !== -1) return false;
  for (const p of (c.permissions || [])) {
    if (String(p) === 'review') return true;
  }
  return false;
};

const daysToWednesday = ((3 - $now.weekday) + 7) % 7 === 0 ? 7 : ((3 - $now.weekday) + 7) % 7;
const dueDate = $now.plus({ days: daysToWednesday }).set({ hour: 17, minute: 0, second: 0, millisecond: 0 }).toFormat('yyyy-MM-dd HH:mm:ss');
const stamp = $now.toFormat('ddMMyy');
const out = [];

for (const pid of Object.keys(byProject)) {
  const projectName = meta[pid] || '';
  const data = byProject[pid];
  if (!data.keys.length) continue;

  const primary = {};
  const fallback = {};
  const emailById = {};
  for (const c of data.contributors) {
    if (!canReview(c)) continue;
    emailById[String(c.user_id)] = String(c.email || '');
    for (const l of (c.languages || [])) {
      if (l.is_writable !== true) continue;
      const iso = String(l.lang_iso || '');
      if (!iso || isSource(iso) || !isTranslatable(iso)) continue;
      const bucket = Number(c.role_id) === LINGUIST_ROLE_ID ? primary : fallback;
      if (!bucket[iso]) bucket[iso] = [];
      if (bucket[iso].indexOf(c.user_id) === -1) bucket[iso].push(c.user_id);
    }
  }

  const langNeed = {};
  const keyEntries = [];
  let skippedUntranslated = 0;
  let skippedArchivedOrHidden = 0;
  for (const k of data.keys) {
    if (k.is_archived === true || k.is_hidden === true) {
      skippedArchivedOrHidden = skippedArchivedOrHidden + 1;
      continue;
    }
    let qualifies = false;
    for (const t of (k.translations || [])) {
      const iso = String(t.language_iso || '');
      if (!iso || isSource(iso) || !isTranslatable(iso)) continue;
      if (isEmpty(t.translation)) continue;
      if (t.is_reviewed === true && t.is_unverified !== true) continue;
      qualifies = true;
      langNeed[iso] = (langNeed[iso] || 0) + 1;
    }
    if (qualifies) {
      keyEntries.push({ key_id: k.key_id, tags: Array.isArray(k.tags) ? k.tags : [], base_words: Number(k.base_words) || 0 });
    } else {
      skippedUntranslated = skippedUntranslated + 1;
    }
  }
  if (!keyEntries.length) continue;

  const languages = [];
  const gaps = [];
  const gapLanguages = [];
  const assignees = {};
  for (const iso of Object.keys(langNeed)) {
    const users = (primary[iso] && primary[iso].length) ? primary[iso] : (fallback[iso] || []);
    if (users.length) {
      languages.push({ language_iso: iso, users: users });
      const emails = [];
      for (const u of users) emails.push(emailById[String(u)] || String(u));
      assignees[iso] = emails;
    } else {
      gaps.push({ language_iso: iso, strings_needing_review: langNeed[iso] });
      gapLanguages.push(iso);
    }
  }
  if (!languages.length) continue;

  const naming = deriveLabel(projectName);
  const chunkCount = Math.ceil(keyEntries.length / MAX_KEYS_PER_TASK);
  for (let c = 0; c < chunkCount; c++) {
    const slice = keyEntries.slice(c * MAX_KEYS_PER_TASK, (c + 1) * MAX_KEYS_PER_TASK);
    const keyIds = [];
    let sourceWords = 0;
    for (const e of slice) {
      keyIds.push(Number(e.key_id));
      sourceWords = sourceWords + (e.base_words || 0);
    }
    const suffix = chunkCount > 1 ? ' (part ' + (c + 1) + ' of ' + chunkCount + ')' : '';
    out.push({ json: {
      projectId: pid,
      projectName: projectName,
      projectLabel: naming.label,
      projectSide: naming.side,
      taskTitle: naming.label + '_' + stamp + ' ' + naming.side + suffix,
      taskDescription: DESCRIPTION,
      dueDate: dueDate,
      keyIds: keyIds,
      keyTags: slice,
      sourceWords: sourceWords,
      totalWords: sourceWords * languages.length,
      languages: languages,
      languageCount: languages.length,
      assigneesByLanguage: assignees,
      gaps: gaps,
      gapLanguages: gapLanguages,
      skippedUntranslatedKeys: skippedUntranslated,
      skippedArchivedOrHiddenKeys: skippedArchivedOrHidden,
      chunk: c + 1,
      chunkCount: chunkCount,
      fetchProblems: fetchProblems
    } });
  }
}
return out;

const r = $json || {};
const plan = $('Build Review Task Plans').item.json || {};
const task = r.task || {};
const ok = !!task.task_id;
let errText = null;
if (!ok) {
  if (r.error) errText = typeof r.error === 'string' ? r.error : JSON.stringify(r.error).slice(0, 400);
  else errText = JSON.stringify(r).slice(0, 400);
}
return { json: {
  ok: ok,
  taskId: task.task_id || null,
  projectId: plan.projectId,
  projectName: plan.projectName,
  taskTitle: plan.taskTitle,
  keyCount: (plan.keyIds || []).length,
  languageCount: plan.languageCount || 0,
  gapLanguages: plan.gapLanguages || [],
  keyTags: ok ? (plan.keyTags || []) : [],
  error: errText
} };

const TAG = 'to_review';
const UNASSIGNED_TAG = 'review_unassigned';
const BATCH = 50;
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.ok) continue;
  const flagUnassigned = (j.gapLanguages || []).length > 0;
  const updates = [];
  for (const k of (j.keyTags || [])) {
    const tags = [];
    for (const t of (k.tags || [])) {
      if (t !== TAG) tags.push(t);
    }
    if (flagUnassigned && tags.indexOf(UNASSIGNED_TAG) === -1) tags.push(UNASSIGNED_TAG);
    updates.push({ key_id: Number(k.key_id), tags: tags, merge_tags: false });
  }
  for (let i = 0; i < updates.length; i = i + BATCH) {
    out.push({ json: {
      projectId: j.projectId,
      projectName: j.projectName,
      taskId: j.taskId,
      keys: updates.slice(i, i + BATCH)
    } });
  }
}
return out;

const created = [];
const failed = [];
const gaps = [];
for (const item of $('Confirm Task Created').all()) {
  const j = item.json || {};
  if (j.ok) {
    created.push({ project: j.projectName || j.projectId, taskId: j.taskId, keys: j.keyCount, languages: j.languageCount });
  } else {
    failed.push({ project: j.projectName || j.projectId, error: j.error });
  }
  for (const iso of (j.gapLanguages || [])) {
    gaps.push({ project: j.projectName || j.projectId, language: iso });
  }
}
let untagged = 0;
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.keys)) untagged = untagged + j.keys.length;
}
return [{ json: {
  runAt: $now.toISO(),
  tasksCreated: created.length,
  tasksFailed: failed.length,
  keysUntagged: untagged,
  created: created,
  failed: failed,
  languagesWithNoEligibleReviewer: gaps
} }];

const SOURCE_PREFIX = 'en';
const LINGUIST_ROLE_ID = 4;
const BLOCKED_EMAILS = ['support@lokalise.com'];
const canReview = (c) => {
  if (c.is_admin === true) return false;
  if (c.is_pending === true) return false;
  if (BLOCKED_EMAILS.indexOf(String(c.email)) !== -1) return false;
  for (const p of (c.permissions || [])) {
    if (String(p) === 'review') return true;
  }
  return false;
};
const meta = {};
for (const p of $('Flatten Projects').all()) {
  const j = p.json || {};
  meta[String(j.projectId)] = j.projectName || '';
}
const byProject = {};
const errors = [];
const all = $input.all();
for (const item of all) {
  const b = item.json || {};
  if (b.error) {
    errors.push(String(typeof b.error === 'string' ? b.error : JSON.stringify(b.error)).slice(0, 200));
    continue;
  }
  const pid = b.project_id ? String(b.project_id) : '(no project_id)';
  if (!byProject[pid]) byProject[pid] = { keys: 0, archived: 0, contributors: 0, reviewCapable: 0, linguists: 0, langs: {} };
  const e = byProject[pid];
  if (Array.isArray(b.keys)) {
    for (const k of b.keys) {
      if (k.is_archived === true || k.is_hidden === true) { e.archived = e.archived + 1; continue; }
      e.keys = e.keys + 1;
    }
  }
  if (Array.isArray(b.contributors)) {
    for (const c of b.contributors) {
      e.contributors = e.contributors + 1;
      if (!canReview(c)) continue;
      e.reviewCapable = e.reviewCapable + 1;
      if (Number(c.role_id) === LINGUIST_ROLE_ID) e.linguists = e.linguists + 1;
      for (const l of (c.languages || [])) {
        if (l.is_writable !== true) continue;
        const iso = String(l.lang_iso || '');
        if (!iso || iso.toLowerCase().indexOf(SOURCE_PREFIX) === 0) continue;
        e.langs[iso] = (e.langs[iso] || 0) + 1;
      }
    }
  }
}
const rows = [];
let total = 0;
for (const pid of Object.keys(byProject)) {
  const e = byProject[pid];
  total = total + e.keys;
  if (e.keys > 0) {
    rows.push({ project: meta[pid] || pid, toReviewKeys: e.keys, archivedOrHiddenSkipped: e.archived, contributors: e.contributors, reviewCapable: e.reviewCapable, linguistReviewers: e.linguists, coveredLanguages: Object.keys(e.langs).length });
  }
}
return [{ json: { itemsIn: all.length, projectsSeen: Object.keys(byProject).length, totalToReviewKeys: total, projectsWithWork: rows.length, fetchErrors: errors.slice(0, 10), rows: rows } }];

const SOURCE_NAMES = { en: 'English' };
const INTERNAL_MARKER = 'futuremedia';
const clean = (s) => {
  let v = String(s || '');
  while (v.length && v.charAt(v.length - 1) === '*') v = v.slice(0, v.length - 1);
  return v.trim();
};
const person = (fullname, email) => {
  const n = String(fullname || '').trim();
  const e = String(email || '').trim();
  if (!e) return n;
  if (e.toLowerCase().indexOf(INTERNAL_MARKER) !== -1) return n || 'FutureMedia';
  if (!n) return e;
  return n + ' (' + e + ')';
};
const fmtDate = (s) => {
  const d = String(s || '').slice(0, 10);
  if (!d) return '';
  const dt = DateTime.fromFormat(d, 'yyyy-MM-dd');
  return dt.isValid ? dt.toFormat('MMMM d, yyyy') : d;
};
const sanitiseTab = (s) => {
  let v = String(s || '');
  v = v.split('[').join('(').split(']').join(')').split(':').join(' -');
  v = v.split('*').join('x').split('?').join('').split('/').join(' of ').split('\\').join(' of ');
  return v.slice(0, 95).trim();
};
const out = [];
for (const item of $input.all()) {
  const b = item.json || {};
  if (b.error) continue;
  const t = b.task || {};
  if (!t.task_id) continue;
  const title = String(t.title || ('Task ' + t.task_id));
  const srcIso = String(t.source_language_iso || 'en');
  const srcName = SOURCE_NAMES[srcIso] || srcIso;
  const langs = t.languages || [];
  let perLangWords = 0;
  if (langs.length) perLangWords = langs[0].words_count || 0;
  const grid = [];
  grid.push(['Task name', title]);
  grid.push(['Task description', String(t.description || '')]);
  grid.push(['Type', String(t.task_type || '')]);
  grid.push(['Created at', fmtDate(t.created_at)]);
  grid.push(['Created by', person(t.created_by_fullname, t.created_by_email)]);
  grid.push(['Due date', fmtDate(t.due_date)]);
  grid.push(['Source words', perLangWords]);
  grid.push(['Words total', t.words_count || 0]);
  grid.push(['Keys total', t.keys_count || 0]);
  grid.push(['Segments total', '']);
  grid.push(['Repetitions', '']);
  grid.push(['']);
  grid.push(['', 'TM 100%', 'TM 95-99%', 'TM 85-94%', 'TM 75-84%', 'TM 50-74%', 'TM 0-49%', 'Assignees']);
  let pending = 0;
  for (const l of langs) {
    const tm = (l.tm_leverage && l.tm_leverage.value) ? l.tm_leverage.value : {};
    if (l.tm_leverage && l.tm_leverage.status !== 'completed') pending = pending + 1;
    const who = [];
    for (const u of (l.users || [])) {
      const label = person(u.fullname, u.email);
      if (label) who.push(label);
    }
    grid.push([
      srcName + ' (' + srcIso + ') → ' + clean(l.language_name) + ' (' + String(l.language_iso) + ')',
      tm['100%'] || 0,
      tm['95%+'] || 0,
      tm['85%+'] || 0,
      tm['75%+'] || 0,
      tm['50%+'] || 0,
      tm['0%+'] || 0,
      who.join(', ')
    ]);
  }
  out.push({ json: {
    taskId: t.task_id,
    taskTitle: title,
    tabName: sanitiseTab(title),
    projectName: b.project_name || '',
    languageCount: langs.length,
    analysisPending: pending,
    rowCount: grid.length,
    grid: grid
  } });
}
return out;

const b = $input.first().json || {};
if (b.error) return [];
const keep = {};
for (const it of $('Build Tab Grid').all()) {
  const j = it.json || {};
  if (j.tabName) keep[String(j.tabName)] = true;
}
const requests = [];
const hiding = [];
const staying = [];
for (const s of (b.sheets || [])) {
  const p = s.properties || {};
  const title = String(p.title || '');
  if (keep[title]) { staying.push(title); continue; }
  if (p.hidden === true) continue;
  hiding.push(title);
  requests.push({ updateSheetProperties: { properties: { sheetId: p.sheetId, hidden: true }, fields: 'hidden' } });
}
if (!staying.length) return [{ json: { skipped: true, reason: 'no tab from this run is visible - refusing to hide every tab', requests: [] } }];
if (!requests.length) return [{ json: { skipped: true, reason: 'nothing to hide', requests: [] } }];
return [{ json: { tabsCreatedThisRun: staying, tabsHidden: hiding, hideCount: hiding.length, requests: requests } }];
